mapper.select:
SELECT DISTINCT p.id, p.name, p.age, p.gender, p.location, p.bio, p.occupation, p.education, 
       p.looking_for, p.age_range_min, p.age_range_max, p.max_distance, 
       p.is_active, p.created_date, p.last_active
FROM user_profiles p

    INNER JOIN user_interests i ON p.id = i.user_profile_id

WHERE p.is_active = true

    AND p.age >= #{minAge}


    AND p.age <= #{maxAge}


    AND p.gender = #{gender}


    AND LOWER(p.location) LIKE LOWER(CONCAT('%', #{location}, '%'))


    AND i.interest IN

        #{interest}


ORDER BY p.last_active DESC

mapper.insert:
INSERT INTO user_profiles (
    id, name, age, gender, location, bio, occupation, education,
    looking_for, age_range_min, age_range_max, max_distance, 
    is_active, created_date, last_active
) VALUES (
    #{id}, #{name}, #{age}, #{gender}, #{location}, #{bio}, #{occupation}, #{education},
    #{lookingFor}, #{ageRangeMin}, #{ageRangeMax}, #{maxDistance}, 
    #{isActive}, #{createdDate}, #{lastActive}
)
